using System.ComponentModel.DataAnnotations;
namespace HealthCare_Portal.ViewModels;
public sealed class RegisterPatientViewModel { [Required, StringLength(100)] public string FirstName { get; set; } = ""; [StringLength(100)] public string? LastName { get; set; } [Required] public string Gender { get; set; } = ""; [Required, DataType(DataType.Date)] public DateTime DOB { get; set; } [StringLength(10)] public string? BloodGroup { get; set; } [Required, Phone] public string Phone { get; set; } = ""; [EmailAddress] public string? Email { get; set; } [StringLength(500)] public string? Address { get; set; } [Required, StringLength(100)] public string Username { get; set; } = ""; [Required, DataType(DataType.Password)] public string Password { get; set; } = ""; [Required, Compare(nameof(Password)), DataType(DataType.Password)] public string ConfirmPassword { get; set; } = ""; }
